/* Тело «Начало списка»; глубину считает обёртка ниже. */
static fl_status kompilyator_flang_nachalo_spiska_body(fl_ctx *ctx, fl_value simvoly, fl_value skolko, fl_value *result, fl_error *error) {
  if (skolko.tag != FL_NUMBER) FL_TRY(fl_not_order(ctx, skolko, fl_number(0.0), error));
  bool fl_t109 = false;
  FL_TRY(fl_cond(ctx, fl_flag(skolko.as.number <= 0.0), &fl_t109, error));
  if (fl_t109) {
    *result = kompilyator_flang_text_175;
    return FL_OK;
  } else {
    if (fl_chain_empty(simvoly)) {
      *result = kompilyator_flang_text_175;
      return FL_OK;
    } else if (fl_chain_cons(simvoly)) {
      const fl_value golova = fl_chain_head(simvoly); /* голова «голова» */
      const fl_value hvost = fl_chain_tail(simvoly); /* хвост «хвост» */
      if (skolko.tag != FL_NUMBER) FL_TRY(fl_not_numbers(ctx, "sub", skolko, fl_number(1.0), error));
      fl_value fl_t110 = fl_nothing();
      FL_TRY(kompilyator_flang_nachalo_spiska(ctx, hvost, fl_number(skolko.as.number - 1.0), &fl_t110, error));
      fl_value fl_t111 = fl_nothing();
      FL_TRY(fl_concat(ctx, golova, fl_t110, &fl_t111, error));
      *result = fl_t111;
      return FL_OK;
    } else {
      return fl_match_fail(ctx, simvoly, error);
    }
  }
}

/*
 * Функция flang «Начало списка».
 *
 * Тотальная: завершение доказано анализом завершаемости (totality.mjs).
 *
 * Рекурсивная: считает глубину, на превышении — FLANG_RECURSION_LIMIT.
 * @param simvoly — «символы»: список: строка
 * @param skolko — «сколько»: число
 * @return значение: строка
 */
fl_status kompilyator_flang_nachalo_spiska(fl_ctx *ctx, fl_value simvoly, fl_value skolko, fl_value *result, fl_error *error) {
  FL_TRY(fl_enter(ctx, "Начало списка", error));
  {
    const fl_mark region = fl_region_open(ctx);
    const fl_status status = kompilyator_flang_nachalo_spiska_body(ctx, simvoly, skolko, result, error);
    fl_leave(ctx);
    return fl_region_close(ctx, region, status, result, error);
  }
}

