        fl_value fl_t688 = fl_nothing();
        FL_TRY(fl_field_get(ctx, chtenie, "значение", &fl_t688, error));
        fl_value fl_t689 = fl_nothing();
        FL_TRY(kompilyator_flang_token_literala(ctx, fl_t688, nomer, mesto, &fl_t689, error));
