/* Тело «Пропустить пояснения»; глубину считает обёртка ниже. */
static fl_status kompilyator_flang_propustit_poyasneniya_body(fl_ctx *ctx, fl_value r, fl_value *result, fl_error *error) {
  for (;;) {
    fl_value fl_t1578 = fl_nothing();
    FL_TRY(kompilyator_flang_eto_vid(ctx, r, kompilyator_flang_text_228, &fl_t1578, error));
    bool fl_t1579 = false;
    FL_TRY(fl_cond(ctx, fl_t1578, &fl_t1579, error));
    fl_value fl_t1580 = fl_nothing();
    if (fl_t1579) {
      fl_value fl_t1581 = fl_nothing();
      FL_TRY(fl_field_get(ctx, r, "поток", &fl_t1581, error));
      fl_value fl_t1582 = fl_nothing();
      FL_TRY(fl_field_get(ctx, fl_t1581, "т0", &fl_t1582, error));
      fl_value fl_t1583 = fl_nothing();
      FL_TRY(fl_field_get(ctx, fl_t1582, "в ёлочках", &fl_t1583, error));
      bool fl_t1584 = false;
      FL_TRY(fl_cond(ctx, fl_t1583, &fl_t1584, error));
      fl_value fl_t1585 = fl_nothing();
      if (fl_t1584) {
        fl_t1585 = fl_flag(false);
      } else {
        fl_t1585 = fl_flag(true);
      }
      fl_t1580 = fl_t1585;
    } else {
      fl_t1580 = fl_flag(false);
    }
    bool fl_t1586 = false;
    FL_TRY(fl_cond(ctx, fl_t1580, &fl_t1586, error));
    if (fl_t1586) {
      fl_value fl_t1587 = fl_nothing();
      FL_TRY(kompilyator_flang_shagnut(ctx, r, &fl_t1587, error));
      r = fl_t1587;
      /* виток цикла — тоже шаг: незавершающийся самовызов обязан упереться в лимит */
      FL_TRY(fl_tick(ctx, "Пропустить пояснения", error));
      continue;
    } else {
      *result = r;
      return FL_OK;
    }
  }
}

/*
 * Функция flang «Пропустить пояснения».
 *
 * Обычная (не тотальная): завершение не доказано, зацикливание не ловится.
 *
 * Хвостовой самовызов развёрнут в цикл: стек не растёт.
 *
 * Рекурсивная: считает глубину, на превышении — FLANG_RECURSION_LIMIT.
 * @param r — «р»: «Разборщик»
 * @return значение: «Разборщик»
 */
fl_status kompilyator_flang_propustit_poyasneniya(fl_ctx *ctx, fl_value r, fl_value *result, fl_error *error) {
  FL_TRY(fl_enter(ctx, "Пропустить пояснения", error));
  {
    const fl_mark region = fl_region_open(ctx);
    const fl_status status = kompilyator_flang_propustit_poyasneniya_body(ctx, r, result, error);
    fl_leave(ctx);
    return fl_region_close(ctx, region, status, result, error);
  }
}

